def download_image(photo_id):
    url = f"https://images.unsplash.com/{photo_id}?w=800&h=450&fit=crop&auto=format&q=80"
    tmp = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False)
    try:
        req = urllib.request.Request(url)
        req.add_header("User-Agent", "Mozilla/5.0")
        with urllib.request.urlopen(req, timeout=30) as resp:
            tmp.write(resp.read())
        tmp.close()
        return tmp.name
    except Exception as e:
        tmp.close()
        os.unlink(tmp.name)
        print(f"  이미지 다운로드 실패 ({photo_id}): {e}")
        return None


def upload_image_to_wp(file_path, filename, alt_text):
    with open(file_path, "rb") as f:
        image_data = f.read()
    req = urllib.request.Request(MEDIA_API, data=image_data, method="POST")
    req.add_header("Authorization", f"Basic {AUTH}")
    req.add_header("Content-Type", "image/jpeg")
    req.add_header("Content-Disposition", f'attachment; filename="{filename}.jpg"')
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            result = json.loads(resp.read().decode("utf-8"))
            media_id = result.get("id")
            media_url = result.get("source_url", "")
            if media_id and alt_text:
                update_data = json.dumps({"alt_text": alt_text}).encode("utf-8")
                update_req = urllib.request.Request(f"{MEDIA_API}/{media_id}", data=update_data, method="POST")
                update_req.add_header("Authorization", f"Basic {AUTH}")
                update_req.add_header("Content-Type", "application/json")
                try: urllib.request.urlopen(update_req, timeout=15)
                except: pass
            return media_id, media_url
    except Exception as e:
        print(f"  WP 업로드 실패: {e}")
        return None, None


def upload_all_images():
    total = sum(len(imgs) for imgs in IMAGES.values())
    uploaded = failed = 0
    print(f"{'='*60}\n이미지 업로드 시작 (총 {total}장)\n{'='*60}")
    for slug, img_list in IMAGES.items():
        UPLOADED_IMAGES[slug] = []
        for idx, (photo_id, alt_text) in enumerate(img_list):
            filename = f"xl-{slug}-{idx+1}"
            tmp_path = download_image(photo_id)
            if not tmp_path:
                UPLOADED_IMAGES[slug].append(("", "", alt_text)); failed += 1; continue
            media_id, wp_url = upload_image_to_wp(tmp_path, filename, alt_text)
            os.unlink(tmp_path)
            if wp_url:
                UPLOADED_IMAGES[slug].append((media_id, wp_url, alt_text)); uploaded += 1
                print(f"  [{uploaded+failed}/{total}] OK | {filename}")
            else:
                UPLOADED_IMAGES[slug].append(("", "", alt_text)); failed += 1
            time.sleep(0.5)
    print(f"\n이미지 업로드 완료: 성공 {uploaded}, 실패 {failed}\n")


def get_image_html(slug, index):
    imgs = UPLOADED_IMAGES.get(slug, [])
    if index >= len(imgs): return ""
    media_id, wp_url, alt_text = imgs[index]
    if not wp_url: return ""
    return f'<figure style="margin:32px 0;text-align:center;"><img src="{wp_url}" alt="{alt_text}" style="width:100%;max-width:800px;height:auto;border-radius:12px;box-shadow:0 2px 12px rgba(0,0,0,0.10);" loading="lazy" /><figcaption style="margin-top:8px;font-size:13px;color:#6b7280;">{alt_text}</figcaption></figure>'


def get_featured_image_id(slug):
    imgs = UPLOADED_IMAGES.get(slug, [])
    return imgs[0][0] if imgs and imgs[0][0] else None


def make_cta(cta):
    border_style = f"border:{cta['border']};" if cta.get("border") else ""
    return f'<div style="background:{cta["bg"]};{border_style}border-radius:12px;padding:28px 32px;margin:32px 0;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px;"><div><p style="margin:0 0 6px;font-size:18px;font-weight:700;color:{cta["text_color"]};">{cta["text"]}</p><p style="margin:0;font-size:14px;color:{cta["desc_color"]};">{cta["desc"]}</p></div><a href="{cta["url"]}" target="_blank" rel="noopener noreferrer" style="background:{cta["btn_bg"]};color:{cta["btn_color"]};padding:12px 24px;border-radius:8px;font-weight:700;text-decoration:none;white-space:nowrap;font-size:15px;">바로가기 &rarr;</a></div>'


def build_content(post):
    parts = []
    slug = post.get("slug", "")
    parts.append(f'<p style="font-size:17px;line-height:1.8;margin-bottom:24px;">{post["intro"]}</p>')
    img1 = get_image_html(slug, 0)
    if img1: parts.append(img1)
    sections = post["sections"]
    ctas = post["ctas"]
    num_sections = len(sections)
    img2_pos = max(2, int(num_sections * 0.6))
    for i, (title, body) in enumerate(sections):
        parts.append(f'<h2 style="font-size:22px;font-weight:700;margin:40px 0 16px;border-left:4px solid #2563eb;padding-left:12px;">{title}</h2>')
        parts.append(body)
        if i == 1 and len(ctas) > 0: parts.append(make_cta(ctas[0]))
        elif i == num_sections // 2 and len(ctas) > 1: parts.append(make_cta(ctas[1]))
        if i == img2_pos:
            img2 = get_image_html(slug, 1)
            if img2: parts.append(img2)
    parts.append('<h2 style="font-size:22px;font-weight:700;margin:40px 0 16px;border-left:4px solid #2563eb;padding-left:12px;">자주 묻는 질문 (FAQ)</h2>')
    for q, a in post["faq"]:
        parts.append(f'<h3 style="font-size:17px;font-weight:600;color:#1e40af;margin:20px 0 8px;">Q. {q}</h3>')
        parts.append(f'<p style="margin:0 0 16px;line-height:1.8;">A. {a}</p>')
    if len(ctas) > 2: parts.append(make_cta(ctas[2]))
    return "\n".join(parts)


