def publish(post_data):
    data = json.dumps(post_data).encode("utf-8")
    req = urllib.request.Request(API, data=data, headers={"Authorization": f"Basic {AUTH}", "Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req) as resp:
            result = json.loads(resp.read().decode("utf-8"))
            return result.get("id"), result.get("link", "")
    except urllib.error.HTTPError as e:
        print(f"  HTTP Error {e.code}: {e.read().decode()[:200]}")
        return None, None
    except Exception as e:
        print(f"  Error: {e}")
        return None, None


def main():
    upload_all_images()
    total = len(POSTS)
    print(f"{'='*60}\n총 {total}개 포스트 발행 시작\n{'='*60}")
    for idx, post in enumerate(POSTS, 1):
        content = build_content(post)
        payload = {"title": post["title"], "content": content, "status": "publish", "slug": post["slug"], "categories": [post["cat"]]}
        fid = get_featured_image_id(post["slug"])
        if fid: payload["featured_media"] = fid
        post_id, link = publish(payload)
        if post_id:
            print(f"[{idx}/{total}] OK | ID:{post_id} | {post['title']}")
            if link: print(f"  -> {link}")
        else:
            print(f"[{idx}/{total}] FAIL | {post['title']}")
        time.sleep(1)
    print("\n완료!")


if __name__ == "__main__":
    main()
